import { cp, mkdir, readdir, readFile, rm, stat, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const output = join(root, 'dist');
const marker = join(output, '.arcade-build');
// Only replace a directory previously generated by this script.
try {
  if ((await stat(output)).isDirectory()) {
    if ((await readFile(marker, 'utf8')).trim() !== 'my-arcade-static-v1') throw new Error('dist exists without our build marker; preserving it.');
    await rm(output, { recursive: true });
  }
} catch (error) { if (error.code !== 'ENOENT') throw error; }
await mkdir(output, { recursive: true });
await writeFile(marker, 'my-arcade-static-v1\n');

for (const name of ['index.html', 'audio.js', 'multiplayer.js']) await cp(join(root, name), join(output, name));
const source = join(root, 'games', 'duels'), destination = join(output, 'games', 'duels');
await mkdir(destination, { recursive: true });
for (const name of ['index.html', 'lab.css', 'lab.js', 'weapons.js', 'duel-rules.js', 'multiplayer.js', 'README.md']) {
  await cp(join(source, name), join(destination, name));
}
for (const name of ['assets', 'vendor']) await cp(join(source, name), join(destination, name), { recursive: true });

let files = 0, bytes = 0;
async function measure(directory) {
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const path = join(directory, entry.name);
    if (entry.isDirectory()) await measure(path);
    else { files++; bytes += (await stat(path)).size; }
  }
}
await measure(output);
console.log(`Built static arcade: ${files} files, ${(bytes / 1024 / 1024).toFixed(2)} MiB in dist/`);
